import json

# Read the corrupted config
with open("/root/.nanobot/agents/harper/config.json") as f:
    corrupted = json.load(f)

def extract_value(v):
    """Extract the real value from the [value, {env_vars}] pattern."""
    if isinstance(v, list) and len(v) == 2 and isinstance(v[1], dict):
        # Check if second element is the env vars dict
        keys = v[1].keys()
        if any("NANOBOT" in k for k in keys):
            return extract_value(v[0])  # Recurse in case of nesting
    if isinstance(v, list):
        return [extract_value(i) for i in v]
    if isinstance(v, dict):
        return {k: extract_value(val) for k, val in v.items()}
    return v

cleaned = extract_value(corrupted)
print(json.dumps(cleaned, indent=2, ensure_ascii=False))
